import os, select, time

def read_port(p, timeout=2.0):
    fd = os.open(f"/dev/robot/{p}", os.O_RDONLY | os.O_NONBLOCK)
    buf = b""
    t0 = time.time()
    try:
        while time.time() - t0 < timeout:
            r,_,_ = select.select([fd], [], [], 0.1)
            if fd in r:
                try:
                    chunk = os.read(fd, 4096)
                except BlockingIOError:
                    continue
                if chunk:
                    buf += chunk
                    if b"\n" in buf:
