    while prev[u] is not None:
        D=prev[u]; path.append(D)
        dx,dy=DIRS[D]; u=(u[0]-dx,u[1]-dy)
    return list(reversed(path))

def goto(bot,M,dst):
    p=bfs_path(M,(bot.x,bot.y),dst)
    if p is None: return False
