        if FOUND[0]: return True
        bot.face(D)
        if not bot.step():
            # blocked where map says open: mark wall
            src=(bot.x,bot.y)
            if src in M: M[src]['w'][str(D)]=True
            dx,dy=DIRS[D]; n=(src[0]+dx,src[1]+dy)
            if n in M: M[n]['w'][str((D+180)%360)]=True
            return False
    return True

